package com.mobixournal.format.mobix

import java.io.File
import java.lang.management.ManagementFactory
import org.junit.Assert.assertEquals
import org.junit.Assert.assertThrows
import org.junit.Assert.assertTrue
import org.junit.Test

/**
 * The **hostile corpus** (`mobix-core/src/test/resources/fixtures/mobix-hostile/`, generated by
 * `scripts/make-mobix-hostile-corpus.py`): one committed file per threat in the limits table of
 * `docs/mobix-format.md`, and the smallest legal document beside them.
 *
 * The claim is not "these files fail" — refusing everything would pass that — but that each fails
 * **for its own reason**, in bounded time and without allocating without limit: the refusal names the
 * rule, arrives within seconds, and the legal neighbour still opens. A silent hang or an
 * `OutOfMemoryError` on any of them is the failure this file exists to make loud.
 */
class MobixHostileCorpusTest {

    /** One threat: the file, what it is an instance of, the rule its refusal must name, how to drive it. */
    private data class Threat(
        val file: String,
        val isAn: String,
        val rule: String,
        val read: (File) -> Unit,
    )

    private val corpusDir: File = File(javaClass.getResource("/fixtures/mobix-hostile")!!.toURI())

    private fun paged(file: File, block: (MobixPagedReader) -> Unit) =
        MobixPagedReader(MobixEntrySource.fromFile(file)).use(block)

    private val threats = listOf(
        Threat("01-too-many-entries.mobix", "more entries than one notebook has", "more than 20000 entries") { file ->
            file.inputStream().use { MobixContainer.open(it) }
        },
        Threat("02-deflate-bomb.mobix", "an entry that inflates past the ratio cap", "inflates") { file ->
            file.inputStream().use { MobixContainer.open(it) }
        },
        Threat("03-deep-nesting.mobix", "a page nested past the depth cap", "nests deeper than") { file ->
            paged(file) { reader -> reader.getPage(0) }
        },
        Threat("04-duplicate-entry.mobix", "two entries answering to one name", "appears twice") { file ->
            file.inputStream().use { MobixContainer.open(it) }
        },
        Threat("05-traversal-entry.mobix", "a name that climbs out of the archive", "traverses out of the archive") { file ->
            file.inputStream().use { MobixContainer.open(it) }
        },
        Threat("06-wrong-digest.mobix", "a page whose bytes disagree with the manifest", "does not match the digest") { file ->
            paged(file) { reader -> reader.getPage(0) }
        },
        Threat("07-encrypted-entry.mobix", "an entry the reader cannot decrypt", "not a readable ZIP") { file ->
            file.inputStream().use { MobixContainer.open(it) }
        },
        // The file-backed road reads the directory, so it is the one that can notice it is gone.
        Threat("08-truncated-directory.mobix", "a file cut before its directory", "not a readable ZIP") { file ->
            MobixEntrySource.fromFile(file).close()
        },
    )

    /** Milliseconds a refusal may take before it is indistinguishable from a hang. */
    private val refusalBudgetMs = 5_000L

    /**
     * How much the refusing thread may **allocate** while it turns a hostile file down.
     *
     * Allocation, not heap occupancy: the latter moves with whatever the previous test left behind and
     * says nothing about the file being read. A reader that trusted a declared size would allocate a
     * declared 256 MiB here; the 16 MiB bomb must cost its 16 MiB and no more.
     */
    private val allocationBudgetBytes = 96L * 1024 * 1024

    private val allocationBean =
        (ManagementFactory.getThreadMXBean() as? com.sun.management.ThreadMXBean)
            ?.takeIf { it.isThreadAllocatedMemorySupported }

    private fun allocatedBytes(): Long? = allocationBean?.getCurrentThreadAllocatedBytes()

    @Test
    fun everyThreatIsRefusedForItsOwnReasonInBoundedTime() {
        for (threat in threats) {
            val file = File(corpusDir, threat.file)
            assertTrue("${threat.file} is missing from the corpus", file.isFile)

            val before = allocatedBytes()
            val started = System.nanoTime()
            val failure = assertThrows(
                "${threat.file} (${threat.isAn}) was accepted",
                MobixContainer.MalformedMobixException::class.java,
            ) { threat.read(file) }
            val elapsedMs = (System.nanoTime() - started) / 1_000_000
            val allocated = before?.let { allocatedBytes()!! - it }

            val message = failure.message.orEmpty()
            assertTrue("${threat.file}: the refusal must name the rule, got \"$message\"", threat.rule in message)
            assertTrue("${threat.file}: refused after $elapsedMs ms; a refusal is not a hang", elapsedMs < refusalBudgetMs)
            if (allocated != null) {
                assertTrue(
                    "${threat.file}: allocated ${allocated / 1024 / 1024} MiB while it was refused",
                    allocated < allocationBudgetBytes,
                )
            }
        }
    }

    @Test
    fun theLegalNeighbourStillOpens() {
        // Without this, a reader that refused every archive would pass the test above.
        paged(File(corpusDir, "00-smallest.mobix")) { reader ->
            assertEquals(1, reader.pageCount)
            assertEquals("pg_001", reader.getPage(0).id)
        }
        File(corpusDir, "00-smallest.mobix").inputStream().use { stream ->
            val archive = MobixContainer.open(stream)
            assertEquals(MobixFormat.MIMETYPE, archive.mimetype)
            assertTrue(archive.names.contains(MobixFormat.MANIFEST_ENTRY))
        }
    }

    @Test
    fun theCorpusIsTheOneThisTestDrives() {
        val named = (threats.map { it.file } + "00-smallest.mobix").toSet()
        val present = corpusDir.listFiles().orEmpty()
            .filter { it.name.endsWith(".mobix") }
            .map { it.name }
            .toSet()
        assertEquals(
            "a corpus file no test names, or a named file that is not committed",
            named,
            present,
        )
    }
}
